begin;
select no_plan();
insert into auth.users(id,email) values ('00000000-0000-4000-8000-000000007701','lifecycle-parent@test.local'),('00000000-0000-4000-8000-000000007702','lifecycle-other@test.local');
insert into public.families(id,name,created_by) values ('10000000-0000-4000-8000-000000007701','A','00000000-0000-4000-8000-000000007701'),('10000000-0000-4000-8000-000000007702','B','00000000-0000-4000-8000-000000007702');
insert into public.family_members(family_id,user_id) values ('10000000-0000-4000-8000-000000007701','00000000-0000-4000-8000-000000007701'),('10000000-0000-4000-8000-000000007702','00000000-0000-4000-8000-000000007702');
insert into public.children(id,family_id,name,grade) values ('20000000-0000-4000-8000-000000007701','10000000-0000-4000-8000-000000007701','Child',5);
insert into public.question_bank(id,family_id,grade,subject,topic,kind,stem,expected_answer) values ('40000000-0000-4000-8000-000000007701','10000000-0000-4000-8000-000000007701',5,'Fen','Güneş','open_ended','Güneş neden ışık kaynağıdır?','Kendi ışığını üretir.');
create function pg_temp.content() returns jsonb language sql as $$
 select '{"childId":"20000000-0000-4000-8000-000000007701","grade":5,"title":"Silinecek taslak","purpose":"practice","format":"school","subjects":["Fen"],"topics":[],"target":1,"minutes":null,"difficulty":"orta","kind":"mixed","note":"","step":3,"blocks":[{"kind":"question","id":"40000000-0000-4000-8000-000000007701","source":"manual"}]}'::jsonb;
$$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000007701","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000007701","role":"parent"}}',true);
select lives_ok($$select public.save_prova_draft(gen_random_uuid(),'50000000-0000-4000-8000-000000007701',0,pg_temp.content())$$,'create draft');
select lives_ok($$select public.set_prova_draft_discarded('70000000-0000-4000-8000-000000007701','50000000-0000-4000-8000-000000007701',1,true)$$,'parent removes unassigned draft');
select is(public.get_prova_drafts('50000000-0000-4000-8000-000000007701'),'[]'::jsonb,'removed draft hidden from old and new editors');
select is(public.get_discarded_prova_drafts()->0->>'version','2','removed list preserves version and content');
select is(public.get_discarded_prova_drafts()->0->'content',pg_temp.content(),'questions remain linked for recovery');
select is((select count(*)::int from public.question_bank where id='40000000-0000-4000-8000-000000007701'),1,'removal does not delete the independent question');
select is(public.set_prova_draft_discarded('70000000-0000-4000-8000-000000007701','50000000-0000-4000-8000-000000007701',1,true)->>'version','2','lost-response replay does not increment twice');
select throws_ok($$select public.set_prova_draft_discarded('70000000-0000-4000-8000-000000007701','50000000-0000-4000-8000-000000007701',2,false)$$,'P0001','request_conflict','request cannot be reused for a restore');
select throws_ok($$select public.save_prova_draft(gen_random_uuid(),'50000000-0000-4000-8000-000000007701',2,pg_temp.content())$$,'P0001','prova_draft_removed','matching-version stale editor cannot write removed draft');
select throws_ok($$select public.submit_prova_draft(gen_random_uuid(),'50000000-0000-4000-8000-000000007701',2)$$,'P0001','prova_draft_removed','assignment of removed draft rolls back');
select is((select count(*)::int from public.exams where id='50000000-0000-4000-8000-000000007701'),0,'failed assignment leaves no exam');
select lives_ok($$select public.set_prova_draft_discarded('70000000-0000-4000-8000-000000007702','50000000-0000-4000-8000-000000007701',2,false)$$,'restore same workspace');
select is(public.get_prova_drafts('50000000-0000-4000-8000-000000007701')->0->>'version','3','restore invalidates stale edit versions');
select lives_ok($$select public.set_prova_draft_discarded('70000000-0000-4000-8000-000000007701','50000000-0000-4000-8000-000000007701',1,true)$$,'old removal receipt remains readable');
select is(jsonb_array_length(public.get_discarded_prova_drafts()),0,'old replay does not remove a subsequently restored draft');
select throws_ok($$select public.set_prova_draft_discarded(gen_random_uuid(),'50000000-0000-4000-8000-000000007701',1,true)$$,'P0001','prova_draft_changed','stale removal cannot discard newer work');
select lives_ok($$select public.submit_prova_draft(gen_random_uuid(),'50000000-0000-4000-8000-000000007701',3)$$,'restored draft can be assigned after validation');
select throws_ok($$select public.set_prova_draft_discarded(gen_random_uuid(),'50000000-0000-4000-8000-000000007701',3,true)$$,'P0001','prova_draft_submitted','assigned practice cannot be removed as a draft');
select lives_ok($$select public.save_prova_draft(gen_random_uuid(),'50000000-0000-4000-8000-000000007702',0,pg_temp.content())$$,'second draft');
select lives_ok($$select public.set_prova_draft_discarded(gen_random_uuid(),'50000000-0000-4000-8000-000000007702',1,true)$$,'remove second draft');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000007702","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000007702","role":"parent"}}',true);
select is(public.get_discarded_prova_drafts(),'[]'::jsonb,'other family cannot read removed drafts');
select throws_ok($$select public.set_prova_draft_discarded(gen_random_uuid(),'50000000-0000-4000-8000-000000007702',2,false)$$,'P0001','prova_draft_not_found','other family cannot restore known id');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000007701","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000007701","role":"child"}}',true);
select throws_ok($$select public.get_discarded_prova_drafts()$$,'42501','forbidden','child cannot read removed parent drafts');
select throws_ok($$select public.set_prova_draft_discarded(gen_random_uuid(),'50000000-0000-4000-8000-000000007702',2,false)$$,'42501','forbidden','child cannot restore');
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select throws_ok($$select public.reserve_prova_generation_v3(gen_random_uuid(),'10000000-0000-4000-8000-000000007701','00000000-0000-4000-8000-000000007701','test-hash',1,'{"draft_id":"50000000-0000-4000-8000-000000007702"}','{"schema":"gina.generation-context.v1","promptHash":"test-hash","total":1,"catalogueBound":false,"grade":5,"subject":"Fen","draftScope":{"version":2,"id":"50000000-0000-4000-8000-000000007702"}}')$$,'P0001','prova_draft_changed','new paid generation on removed draft rejected before quota reservation');
select ok(not has_function_privilege('anon','public.set_prova_draft_discarded(uuid,uuid,integer,boolean)','execute'),'anonymous cannot remove drafts');
select ok(not has_table_privilege('authenticated','public.prova_drafts','DELETE'),'clients cannot bypass lifecycle with hard delete');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000007701","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000007701","role":"parent"}}',true);
do $$declare id uuid;begin for n in 1..31 loop
 id:=gen_random_uuid();perform public.save_prova_draft(gen_random_uuid(),id,0,pg_temp.content());
 perform public.set_prova_draft_discarded(gen_random_uuid(),id,1,true);
end loop;end;$$;
create temp table lifecycle_pages as select public.get_discarded_prova_drafts() as first_page;
alter table lifecycle_pages add column second_page jsonb;
update lifecycle_pages set second_page=public.get_discarded_prova_drafts(null,(first_page->29->>'updated_at')::timestamptz,(first_page->29->>'id')::uuid);
select is(jsonb_array_length(first_page),30,'removed drafts use bounded first page') from lifecycle_pages;
select is(jsonb_array_length(second_page),2,'older removed drafts remain reachable') from lifecycle_pages;
select is((select count(distinct v->>'id')::int from lifecycle_pages,jsonb_array_elements(first_page||second_page) v),32,'pages do not duplicate or omit records');
select is(public.get_discarded_prova_drafts('20000000-0000-4000-8000-000000007799'),'[]'::jsonb,'child filter applied before pagination');
select is(jsonb_array_length(public.get_discarded_prova_drafts('20000000-0000-4000-8000-000000007701')),30,'selected child retains own page');
select * from finish();
rollback;
